-- 144_productos_resto_categorias_drive.sql (2026-10-29)
--
-- Productos armados con las fotos NUEVAS de las carpetas Supermercado, Verdulería, Lácteos, Carnicería,
-- Tecnología y Zapatería del Drive de la cuenta (el resto de las categorías), mezclando rubros: lo del
-- Supermercado se reparte en su rubro natural (verduras -> Verdulería, dulce de leche -> Lácteos,
-- snacks y galletitas -> Kiosco, Don Satur -> Panadería, almacén -> Almacén, el resto -> Supermercado)
-- y los productos de otros rubros se venden también en Super Baradero y Almacén Don José (nunca forrajería).
-- Solo datos, sin cambios de esquema. Mismo criterio que la 125/129/134/141/142/143: nombre, descripción y
-- opciones salen de lo que se ve en cada foto; las variantes (sabores, colores, talles) van como opciones y
-- todas las fotos del mismo producto van en product_images (la primera es la principal).
--
-- ORDEN: aplicar DESPUES de que el deploy con public/img/productos/*.webp, public/img/promos/*.webp
-- y public/img/comercios/*.webp esté en producción; si no, productos, banners y logos salen rotos.
--
-- Comercios NUEVOS (cuentas de prueba, creadas aparte con auth.users + auth.identities, rol vendedor con la
-- bandera app.role_change_authorized; acá se las busca por email, sin la cuenta no se inserta su comercio):
--   Verdulería La Quinta (proyectopdisc+laquinta@gmail.com), Lácteos Santa Rosa (+santarosa),
--   Carnicería La Parrilla (+laparrilla), Zapatería Paso a Paso (+pasoapaso), GamerZone Baradero (+gamerzone).
-- Comercios existentes (seed) que suman productos: Super Baradero, Almacén Don José, Kiosco El Paso,
--   Golosinas Dulce Tentación, Panadería El Sol, Carnicería El Novillo y TecnoCenter Baradero.
-- Ofertas: 13 productos con precio tachado (compare_at_price) y fecha de fin (offer_expires_at).
-- Cupones por comercio nuevo y 3 banners del inicio (home_promos): al final. Las 18 posiciones ya estaban
-- ocupadas: reemplazan la publicidad 2 del espacio c (Panadería El Sol), la 1 del espacio f (Almacén Don José)
-- y la 2 del espacio b (Indumentaria La Moda); esos comercios siguen con sus productos y su página.
--
-- Ningún comercio de prueba tiene alias bancario (no se inventa uno): products_require_transfer_alias
-- (migración 107) se apaga mientras corre y se prende de nuevo al final. Idempotente: un producto
-- no se inserta si el comercio ya tiene uno con el mismo título.
--
-- Quedaron sin subir ~160 fotos chicas (menos de ~37 KB) que el conector de Drive no puede bajar a disco.


insert into public.stores (owner_id, name, status, category_slug, description, zone, hours, contact_method)
select u.id, 'Verdulería La Quinta', 'approved', 'verduleria', 'Frutas y verduras frescas todos los días: de la quinta a tu mesa, en Baradero.', 'Baradero', to_jsonb('Lunes a sábado de 8:00 a 13:00 y de 16:30 a 20:30'::text), 'none'
