update public.home_promos set store_id = (select s.id from public.stores s join auth.users u on u.id = s.owner_id where u.email = 'proyectopdisc+santarosa@gmail.com' limit 1), product_id = (select p.id from public.products p where p.store_id = (select s.id from public.stores s join auth.users u on u.id = s.owner_id where u.email = 'proyectopdisc+santarosa@gmail.com' limit 1) and p.title = 'Dulce de leche repostero Milkaut 400 g' limit 1), image_url = '/img/promos/promo-lacteos-santa-rosa.webp', title = 'Dulce de leche y leche con hasta 14% OFF', is_active = true, updated_at = now() where slot = 'mosaic_f' and position = 1 and (select s.id from public.stores s join auth.users u on u.id = s.owner_id where u.email = 'proyectopdisc+santarosa@gmail.com' limit 1) is not null;
update public.home_promos set store_id = (select s.id from public.stores s join auth.users u on u.id = s.owner_id where u.email = 'proyectopdisc+pasoapaso@gmail.com' limit 1), product_id = (select p.id from public.products p where p.store_id = (select s.id from public.stores s join auth.users u on u.id = s.owner_id where u.email = 'proyectopdisc+pasoapaso@gmail.com' limit 1) and p.title = 'Zuecos tipo Crocs' limit 1), image_url = '/img/promos/promo-zapateria-paso-a-paso.webp', title = 'Zuecos y zapatillas con hasta 17% OFF', is_active = true, updated_at = now() where slot = 'mosaic_b' and position = 2 and (select s.id from public.stores s join auth.users u on u.id = s.owner_id where u.email = 'proyectopdisc+pasoapaso@gmail.com' limit 1) is not null;
